def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    noisy = set()

    # Small components of the marker-like colors are stray pixels.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if color in (0, 4, 7, 8) and len(comp) <= 2:
                noisy.update(comp)

    if not noisy:
        return out

    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    for r, c in noisy:
        cardinal = []
        has_noisy_neighbor = False
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
