            if 0 <= y < h and 0 <= x < w:
                if (y, x) in noisy:
                    has_noisy_neighbor = True
                else:
                    cardinal.append(grid[y][x])

        def most_common(values):
            freq = {}
            for v in values:
                freq[v] = freq.get(v, 0) + 1
            best = max(freq.values())
            return [v for v, n in freq.items() if n == best], freq

        choices, freq = most_common(cardinal)
        if len(choices) == 1:
            replacement = choices[0]
        elif has_noisy_neighbor:
            around = [
                grid[y][x]
                for dy in (-1, 0, 1)
                for dx in (-1, 0, 1)
                if (dy or dx) and 0 <= (y := r + dy) < h
                and 0 <= (x := c + dx) < w and (y, x) not in noisy
            ]
            choices8, freq8 = most_common(around)
            replacement = choices8[0]
        else:
            nonbackground = [v for v in choices if v != background]
            replacement = nonbackground[0] if nonbackground else choices[0]

        out[r][c] = replacement

    return out
